class Solution {
public:
    int minimizeMax(std::vector<int>& nums, int p) {
        std::sort(nums.begin(), nums.end());
        int n = nums.size();
        auto countPairs = [&](int d) {
            int cnt = 0, i = 0;
            while (i < n - 1) {
                if (nums[i + 1] - nums[i] <= d) {
                    cnt++;
                    i += 2;
                } else {
                    i++;
                }
            }
            return cnt;
        };
        int low = 0, high = nums.back() - nums.front();
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (countPairs(mid) >= p) high = mid;
            else low = mid + 1;
        }
        return low;
    }
};

class Solution {
    public int minimizeMax(int[] nums, int p) {
        java.util.Arrays.sort(nums);
        int n = nums.length;
        int low = 0, high = nums[n - 1] - nums[0];
        while (low < high) {
            int mid = low + (high - low) / 2;
            int cnt = 0, i = 0;
            while (i < n - 1) {
                if (nums[i + 1] - nums[i] <= mid) {
                    cnt++;
                    i += 2;
                } else {
                    i++;
                }
            }
            if (cnt >= p) high = mid;
            else low = mid + 1;
        }
        return low;
    }
}

var minimizeMax = function(nums, p) {
    nums.sort((a, b) => a - b);
    const n = nums.length;
    let low = 0, high = nums[n - 1] - nums[0];
    while (low < high) {
        const mid = (low + high) >> 1;
        let cnt = 0, i = 0;
        while (i < n - 1) {
            if (nums[i + 1] - nums[i] <= mid) {
                cnt++;
                i += 2;
            } else {
                i++;
            }
        }
        if (cnt >= p) high = mid;
        else low = mid + 1;
    }
    return low;
};
